#include "stm32f7xx.h"
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

Adafruit_ILI9341 tft(10, 9, 8);

void SystemClock_Config(void);

int main(void) {
  HAL_Init();
  SystemClock_Config();

  tft.begin();
  tft.setRotation(1);

  tft.fillScreen(0x001F);

  tft.setTextColor(0xFFE0);
  tft.setTextSize(3);
  tft.setCursor(20, 10);
  tft.println("STM32F746G-DISCO");

  tft.setTextColor(0xFFFF);
  tft.setTextSize(2);
  tft.setCursor(20, 50);
  tft.println("Register-Level Mode");
  tft.println("No Arduino setup/loop");

  tft.fillRect(20, 100, 120, 60, 0xF800);
  tft.fillRect(160, 100, 120, 60, 0x07E0);
  tft.fillRect(300, 100, 120, 60, 0x001F);

  tft.setTextColor(0xFFFF);
  tft.setTextSize(2);
  tft.setCursor(50, 120);  tft.print("RED");
  tft.setCursor(190, 120); tft.print("GREEN");
  tft.setCursor(325, 120); tft.print("BLUE");

  while (1) {
    HAL_Delay(100);
  }
}

void SystemClock_Config(void) {
}
